from collections import Counter
def transform(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bc=max((c for c in cnt if c),key=lambda c:cnt[c])
    noise=[(r,c) for r in range(H) for c in range(W) if g[r][c] not in (0,bc)]
    rs=[r for r in range(H) for c in range(W) if g[r][c]==bc]
    cs=[c for c in range(W) for r in range(H) if g[r][c]==bc]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    below_noise={c for r,c in noise if r>r1}
    out=[row[:] for row in g]
    for r in range(r0,r1+1):
        rn=[c for rr,c in noise if rr==r]
        if not rn: out[r]=[bc]*W
        else:
            if any(c<c0 for c in rn):
                for c in range(c1+1,W): out[r][c]=bc
            if any(c>c1 for c in rn):
                for c in range(0,c0): out[r][c]=bc
    for r in range(0,r0):
        for c in range(c0,c1+1): out[r][c]=bc
    for r in range(r1+1,H):
        for c in range(c0,c1+1):
            if c not in below_noise: out[r][c]=bc
    return out
